const R=(r,E)=>{switch(r){case"IDLE":if(E.type==="SCAN_INBOUND")return"LOOKING_UP";if(E.type==="OPEN_MANUAL")return"MANUAL_ENTRY";if(E.type==="TRIGGER_CLOSE")return"CONFIRMING_CLOSE";break;case"LOOKING_UP":if(E.type==="PRODUCT_RESOLVED")return E.needsPharma?"AWAITING_PHARMA":"COMMITTING";if(E.type==="ERROR_OCCURRED")return"FEEDBACK_ERROR";break;case"AWAITING_PHARMA":if(E.type==="PHARMA_COMPLETE")return"COMMITTING";if(E.type==="RESET")return"IDLE";break;case"COMMITTING":if(E.type==="COMMIT_COMPLETE")return"FEEDBACK_SUCCESS";if(E.type==="ERROR_OCCURRED")return"FEEDBACK_ERROR";break;case"FEEDBACK_SUCCESS":case"FEEDBACK_ERROR":if(E.type==="RESET")return"IDLE";break;case"MANUAL_ENTRY":if(E.type==="CLOSE_MANUAL")return"IDLE";if(E.type==="SCAN_INBOUND")return"LOOKING_UP";break;case"CONFIRMING_CLOSE":if(E.type==="CANCEL_CLOSE")return"IDLE";break}return r};export{R as s};
